write('oferta','Oferta ubezpieczeń — samochód, dom, życie i firma','Poznaj ofertę ubezpieczeń 8699.pl. OC, AC, dom, mieszkanie, życie, zdrowie, firma oraz podróże. Kontakt z biurami w Kościerzynie i Bytowie.',crumbs('Oferta ubezpieczeń')+'<section class="section alt"><div class="wrap"><div class="section-head"><div><p class="eyebrow">ZACZNIJ OD SWOICH POTRZEB</p><h2>Różne sprawy.<br>Osobiste podejście.</h2></div><p>Zakres polisy warto omówić przed decyzją. Sprawdź wybraną kategorię i przygotuj pytania do doradcy.</p></div>'+servicecards()+'</div></section>'+standard()+partners()+contact())
write('o-nas','O nas — doradcy ubezpieczeniowi od 2001 roku','Poznaj 8699.pl i naszych doradców. Punkty Standard Ergo Hestii w Kościerzynie i Bytowie. Doświadczenie od 2001 roku i bezpośredni kontakt.',crumbs('Poznaj ludzi za Twoją polisą')+B['intro']+standard()+teamsection()+timeline()+media()+'<section class="section alt"><div class="wrap"><div class="section-head"><div><p class="eyebrow">DOŚWIADCZENIE I ROZWÓJ</p><h2>Nasze certyfikaty.</h2></div><p>Dokumenty potwierdzające szkolenia i kompetencje naszego zespołu.</p></div><div class="certificates"><a href="/assets/certyfikat1.webp" target="_blank" rel="noopener"><img loading="lazy" decoding="async" src="/assets/certyfikat1.webp" width="433" height="505" alt="Certyfikat 8699.pl — dokument pierwszy"></a><a href="/assets/certyfikat2.webp" target="_blank" rel="noopener"><img loading="lazy" decoding="async" src="/assets/certyfikat2.webp" width="433" height="505" alt="Certyfikat 8699.pl — dokument drugi"></a></div></div></section>'+contact())
for slug,name,addr,hours,tel,email in offices:
 isko=slug=='koscierzyna'
